<?php
function isLucky($num) {
    $s = (string)$num;
    for ($i = 0; $i < strlen($s); $i++) {
        if ($s[$i] !== '4' && $s[$i] !== '7') {
            return false;
        }
    }
    return true;
}

function countLuckyUpTo($n) {
    $count = 0;
    for ($i = 1; $i <= $n; $i++) {
        if (isLucky($i)) {
            $count++;
        }
    }
    return $count;
}

function factorial($n) {
    if ($n <= 1) return 1;
    $result = 1;
    for ($i = 2; $i <= $n; $i++) {
        $result *= $i;
    }
    return $result;
}

function getKthPermutation($n, $k) {
    // Check if k-th permutation exists
    $total = factorial($n);
    if ($k > $total) {
        return null;
    }

    $k--; // 0-indexed
    $elements = range(1, $n);
    $permutation = [];

    for ($i = 0; $i < $n; $i++) {
        $remaining = $n - $i;
        $fact = factorial($remaining - 1);
        $index = intdiv($k, $fact);
        $permutation[] = $elements[$index];
        array_splice($elements, $index, 1);
        $k %= $fact;
    }

    return $permutation;
}

function solve() {
    $input = trim(fgets(STDIN));
    $parts = explode(' ', $input);
    $n = (int)$parts[0];
    $k = (int)$parts[1];

    // Check if k-th permutation exists
    $total = factorial($n);
    if ($k > $total) {
        echo "-1\n";
        return;
    }

    // Get the k-th permutation
    $permutation = getKthPermutation($n, $k);

    if ($permutation === null) {
        echo "-1\n";
        return;
    }

    // Count positions where both index and value are lucky
    $count = 0;
    for ($i = 1; $i <= $n; $i++) {
        if (isLucky($i) && isLucky($permutation[$i - 1])) {
            $count++;
        }
    }

    echo $count . "\n";
}

